tool_input.command:
$probe = @'
import { spawn } from "node:child_process";
const proxy = process.argv[2];
const child = spawn(process.execPath, [proxy], { stdio: ["pipe","pipe","pipe"], env: process.env });
let out="", err="";
child.stdout.on("data", d => out += d.toString());
child.stderr.on("data", d => err += d.toString());
const send = o => child.stdin.write(JSON.stringify(o) + "\n");
send({jsonrpc:"2.0", id:1, method:"initialize", params:{protocolVersion:"2024-11-05", capabilities:{}, clientInfo:{name:"gwprobe",version:"0"}}});
setTimeout(()=>send({jsonrpc:"2.0", id:2, method:"tools/list", params:{}}), 800);
setTimeout(()=>{
  const lines = out.split(/\r?\n/).filter(Boolean);
  let listed=false;
  for(const l of lines){ try{ const m=JSON.parse(l.replace(/^data:\s*/,'')); if(m.id===1 && m.result) console.log("INIT_OK serverInfo="+JSON.stringify(m.result.serverInfo)); if(m.id===2 && m.result && m.result.tools){ listed=true; console.log("TOOLS_LIST_OK count="+m.result.tools.length+" names="+m.result.tools.map(t=>t.name).join(",")); } }catch{} }
  if(!listed) console.log("TOOLS_LIST_NOT_OK out_head="+out.slice(0,200)+" err_tail="+err.slice(-300));
  process.exit(0);
}, 3500);
'@
$tmp=Join-Path $env:TEMP "gwprobe.mjs"; Set-Content -Path $tmp -Value $probe -Encoding utf8
$proxy="$env:USERPROFILE\.dsh\profiles\web\node_modules\@openviking\dsh-memory-plugin\servers\mcp-proxy.mjs"
& node $tmp $proxy 2>&1

$ts = Get-Date -Format "yyyyMMddHHmmss"
$files = @(
  "$env:USERPROFILE\.dsh\profiles\web\cordis.patch.yml",
  "$env:USERPROFILE\.dsh\mcp-gateway\cordis.patch.yml",
  "$env:USERPROFILE\.dsh\profiles\web\package.json",
  "$env:USERPROFILE\.dsh\profiles\web\pnpm-lock.yaml"
)
foreach($f in $files){
  if(Test-Path $f){ $dst = "$f.bak-ovgw-$ts"; Copy-Item $f $dst -Force; "OK  $dst" } else { "MISSING  $f" }
}

