tool_input.new_string:
  // Mounted last, and deliberately not awaited: the bridge's apply blocks on
  // its first tools/list, so a server that accepts the connection but never
  // answers would otherwise hold up every registration above it.
  // [patch A-1 ovgw] toolSurface gates the MCP tool surface only (memory
  // capture/recall/commit/skills stay mounted). Read raw `input` (pre-schema)
  // so an out-of-schema value is not stripped by buildPluginConfig. Legal
  // values in A-1: 'direct' | 'off'; 'gateway' is reserved for A-2.
  const surface = input.toolSurface ?? "direct";
  if (!["direct", "off"].includes(surface)) {
    ctx.logger?.warn(`[openviking] unknown toolSurface=${surface}, fallback to direct`);
  }
  if (surface !== "off") mountOpenVikingMcp(ctx, config);
  mountOpenVikingSkills(ctx);
}

